<?php
class Account {
public function check(){global $engine;if(isset($_SESSION['mellon_msid'])){$m=query("SELECT * FROM global_msid WHERE token=? LIMIT 1",[$_SESSION['mellon_msid']])->fetch();if(!$m)return false;$u=query("SELECT * FROM global_user WHERE email=? LIMIT 1",[$m['email']])->fetch();if(!$u)return false;$engine->session->data=(object)$u;$_SESSION['mellon_uid']=(int)$u['uid'];$_SESSION['mellon_username']=$u['username'];$_SESSION['mellon_email']=$u['email'];return true;}if(isset($_SESSION['mellon_email'])){$u=query("SELECT * FROM global_user WHERE email=? LIMIT 1",[$_SESSION['mellon_email']])->fetch();if(!$u)return false;$engine->session->data=(object)$u;return true;}return false;}
public function Signup($email,$password,$newsletter,$term){if(!$term||!filter_var($email,FILTER_VALIDATE_EMAIL)||$password==='')return false;if($this->EmailValid($email))return false;$username=substr(preg_replace('/[^A-Za-z0-9_-]/','',explode('@',$email)[0]),0,20);if($username==='')$username='Player'.random_int(1000,9999);query("INSERT INTO global_user (username,email,password,timed,prestige,level) VALUES (?,?,?,?,?,?)",[$username,$email,base64_encode($password),time(),0,0]);return $this->Login($email,$password);}
public function EmailValid($email){return (bool)query("SELECT 1 FROM global_user WHERE email=? LIMIT 1",[$email])->fetchColumn();}
public function Login($login,$pass){global $engine;$u=query("SELECT * FROM global_user WHERE email=? OR username=? LIMIT 1",[$login,$login])->fetch();if(!$u)return false;$stored=(string)$u['password'];if(!hash_equals($stored,base64_encode($pass)))return false;$engine->session->data=(object)$u;$_SESSION['mellon_uid']=(int)$u['uid'];$_SESSION['mellon_username']=$u['username'];$_SESSION['mellon_email']=$u['email'];$_SESSION['mellon_msid']=$engine->database->msid($u['email']);session_regenerate_id(true);return true;}
public function Logout(){unset($_SESSION['mellon_uid'],$_SESSION['mellon_username'],$_SESSION['mellon_email'],$_SESSION['mellon_msid']);}
}
